import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'

import styles from './DebugBasicItem.module.css'

type SomeData = string | boolean | undefined | number | object

const getDataString = (d: SomeData) => {
  if (typeof d === 'boolean') {
    return d ? 'true' : 'false'
  } else if (typeof d === 'object') {
    return JSON.stringify(d, null, 2)
  } else if (typeof d === 'number') {
    return d.toString()
  }
  return d ?? 'undefined'
}

export interface DebugBasicItemProps {
  label: string
  data: SomeData
}

export const DebugBasicItem = ({label, data}: DebugBasicItemProps) => {
  const dataString = getDataString(data)

  return (
    <tr className={styles.tableRow}>
      <td className={styles.labelCell}>{label}</td>
      <td className={styles.valueCell}>{dataString}</td>
      <td className={styles.copyCell}>
        <CopyToClipboardButton textToCopy={dataString} size="small" />
      </td>
    </tr>
  )
}
